import { ReactNode } from 'react';
/**
 * All explicit states managed by the protection engine
 */
export type ProtectionState = 'LOADING' | 'OFFLINE' | 'API_ERROR' | 'UNAUTHORIZED' | 'BLOCKED' | 'EXPIRED' | 'DEMO_EXPIRED' | 'NOT_FOUND' | 'PACKAGE_UPDATE_REQUIRED' | 'VALID';
/**
 * Status values returned from backend WizzTech protection platform
 */
export type ApiStatusValue = 'allowed' | 'blocked' | 'demo_expired' | 'invalid_token' | 'origin_mismatch' | 'not_found' | 'active' | 'expired' | 'unauthorized';
/**
 * Contact options provided dynamically by backend API or fallback
 */
export interface ContactInfo {
    email: string;
    whatsapp: string;
    instagram: string;
    website: string;
}
/**
 * API Response from backend validation server
 */
export interface ProtectionStatusResponse {
    status: ApiStatusValue;
    title?: string;
    description?: string;
    minimumPackageVersion?: string;
    contactInfo?: Partial<ContactInfo>;
    expiryDate?: string;
    clientDomain?: string;
    verifiedAt?: string;
}
/**
 * Request payload sent to WizzTech Platform validation endpoint
 */
export interface ValidationRequestPayload {
    websiteUrl: string;
    origin: string;
    demoToken: string | null;
    incrementView: boolean;
}
/**
 * Props for WizzTechProtectionProvider
 */
export interface WizzTechProtectionProviderProps {
    children: ReactNode;
    /**
     * The WizzTech Protection Platform endpoint URL.
     * Required. Pass your host project's platform URL.
     * Example: platformUrl="https://platform-domain.netlify.app"
     */
    platformUrl: string;
    /**
     * Visual theme mode ('dark' | 'light' | 'auto'). Defaults to 'dark'
     */
    theme?: 'light' | 'dark' | 'auto';
    /**
     * Session cache TTL in minutes. Defaults to 15 minutes
     */
    cacheTtlMinutes?: number;
    /**
     * Optional custom logo component replacement for default placeholder
     */
    customLogo?: ReactNode;
    /**
     * Callback fired when protection state updates
     */
    onStatusChange?: (state: ProtectionState, details?: ProtectionStatusResponse) => void;
}
/**
 * Public metadata and controls provided via useProtection() hook
 */
export interface ProtectionContextValue {
    state: ProtectionState;
    isValid: boolean;
    isOffline: boolean;
    statusDetails: ProtectionStatusResponse | null;
    packageVersion: string;
    lastCheckedAt: string | null;
    retry: () => Promise<void>;
    clearCache: () => void;
}
/**
 * Cached session stored in sessionStorage
 */
export interface CachedProtectionSession {
    data: ProtectionStatusResponse;
    timestamp: number;
    domain: string;
}
